"""Running usage total reported to the Acme billing API.

The total is a 64-bit-range integer: it is NOT masked to signed 32-bit, so accumulation past 2^31
grows instead of wrapping to a negative value (INC-7701). Python ints are arbitrary precision, so
removing the mask from the add path is the whole widening.
"""


class UsageCounter:
    def __init__(self, start=0):
        self._total = int(start)

    def add(self, units):
        self._total += units   # no 32-bit mask -> grows past 2^31 instead of wrapping

    @property
    def total(self):
        return self._total

